import json, glob, os, re, sys
def text_of(c):
    if isinstance(c, str): return c
    return "\n".join(b.get("text","") for b in c if isinstance(b, dict) and b.get("type")=="text")
def count(t):
    bullets = sum(1 for l in t.splitlines() if re.match(r"\s*([-*]|\d+\.)\s", l))
    return len(t.split()), bullets
for f in sorted(glob.glob("poe/*/logs/*/*.jsonl")):
    recs=[json.loads(l) for l in open(f) if l.strip()]
    # find user turns (real prompts) and the last assistant text before next prompt
    turns=[]; cur=None
    for r in recs:
        if r.get("type")=="user" and not r.get("isMeta"):
            c=r["message"]["content"]
            t=text_of(c) if isinstance(c,str) or any(b.get("type")=="text" for b in c if isinstance(b,dict)) else None
            if t is not None and "tool_result" not in str(c)[:50]:
                cur={"prompt":t[:200],"last":None}; turns.append(cur)
        elif r.get("type")=="assistant" and cur is not None:
            t=text_of(r["message"]["content"])
            if t.strip(): cur["last"]=t
    for i,tn in enumerate(turns):
        if tn["last"] and "Next:" in tn["last"]:
            w,b=count(tn["last"])
            print(f, i, repr(tn["prompt"][:120]), "words",w,"bullets",b)
